// RAS test run time (spec §14.12): `describe` / `test` / `expect`, the hooks, the replacements
// of dialogs and outside calls, and the runner. Generated by ras — do not edit.
//
// A test file's top-level statements only declare (`describe` runs its body at once, `test`
// records its body); `run` then runs the tests in the order they were written and reports
// each as one line of JSON. The workbook is put back before every test to what it was after
// the `beforeAll` hooks around the test (spec §14.12.5).
"use strict";
const fs = require("fs");
const os = require("os");
const path = require("path");

module.exports = function createTest(rt) {
    const { RasError, RDate, CVErr, Struct } = rt;
    const projectRoot = () => path.resolve(rt.config().root || ".");

    // ------------------------------------------------------------------------ the tree

    function suite(name, parent, mode) {
        return { suite: true, name, parent, mode, children: [], hooks: { beforeAll: [], afterAll: [], beforeEach: [], afterEach: [] }, line: 0 };
    }
    const rootSuite = suite(null, null, "run");
    /** The `describe` whose body is running (declarations go into it). */
    let declaring = rootSuite;
    /** Set while the tests run: declaring then is a mistake. */
    let started = false;
    /** The test that is running, or the hook: what `printed()`, the matchers and the dialogs report to. */
    let running = null;

    /** The position in a RAS source of the first RAS frame of a stack trace. */
    function position(stack) {
        const m = /([^\s()]+\.ras):(\d+):(\d+)/.exec(String(stack || ""));
        if (!m) return null;
        const abs = m[1].replace(/^file:\/\//, "");
        const rel = path.relative(projectRoot(), abs);
        const file = !rel || rel.startsWith("..") || path.isAbsolute(rel) ? abs : rel.split(path.sep).join("/");
        return { file, line: +m[2], column: +m[3] };
    }
    function here() {
        const p = position(new Error().stack);
        return p ? p.line : 0;
    }

    function declare(what) {
        if (started) throw rt.makeError(`\`${what}\` はテストの本体やフックの中では呼べません（テストファイルのトップレベルか \`describe\` の本体に書いてください）`, 5);
    }
    function addSuite(name, body, mode, args) {
        declare("describe");
        const s = suite(String(name), declaring, mode);
        s.line = here();
        declaring.children.push(s);
        const outer = declaring;
        declaring = s;
        try {
            if (typeof body === "function") body(...(args || []));
        } finally {
            declaring = outer;
        }
    }
    function addTest(name, body, mode, options, args) {
        declare("test");
        const timeout = options != null && typeof options === "object" && options.timeout > 0 ? options.timeout : null;
        declaring.children.push({ suite: false, name: String(name), parent: declaring, mode, body: typeof body === "function" ? body : null, args: args || [], timeout, line: here() });
    }

    /** The name of a case of `.each` (as `testing.rs` of the compiler writes it for the list). */
    function caseName(template, row) {
        const values = Array.isArray(row) ? row : row instanceof Struct ? [] : [row];
        let next = 0;
        return String(template).replace(/%([%sidf])|\$([A-Za-z_][A-Za-z0-9_]*)/g, (all, spec, field) => {
            if (field !== undefined) return row instanceof Struct && field in row ? show(row[field], true) : all;
            if (spec === "%") return "%";
            const v = values[next++];
            if (spec === "i" || spec === "d") return typeof v === "number" ? String(Math.trunc(v)) : show(v, true);
            return show(v, true);
        });
    }
    function each(add, mode) {
        return (table) => (name, body, options) => {
            const rows = Array.isArray(table) ? table : table == null ? [] : Array.from(rt.iter(table));
            for (const row of rows) {
                // A tuple or an array gives its elements as arguments, a struct itself.
                const args = Array.isArray(row) ? row : [row];
                add(caseName(name, row), body, mode, options, args);
            }
        };
    }
    function declarer(add, withTodo) {
        const f = (name, body, options) => add(name, body, "run", options);
        f.skip = (name, body, options) => add(name, body, "skip", options);
        f.only = (name, body, options) => add(name, body, "only", options);
        f.each = each((name, body, mode, options, args) => add(name, body, mode, options, args), "run");
        if (withTodo) f.todo = (name) => add(name, null, "todo");
        return f;
    }
    const describe = declarer((name, body, mode, _options, args) => addSuite(name, body, mode, args), false);
    const test = declarer(addTest, true);

    function hook(kind) {
        return (fn) => {
            declare(kind);
            declaring.hooks[kind].push(fn);
        };
    }

    // ------------------------------------------------------------------------ values as text

    /** A value as the failure of a matcher shows it. `plain`: text without quotes (names of cases). */
    function show(v, plain) {
        if (v === undefined) return "undefined";
        if (v === null) return "Empty";
        if (v === rt.Nothing) return "Nothing";
        switch (typeof v) {
            case "string":
                return plain ? v : JSON.stringify(v);
            case "number":
                return rt.numStr(v);
            case "boolean":
                return v ? "true" : "false";
            case "function":
                return "() => …";
            default:
        }
        if (v instanceof RDate) return plain ? v.toString() : `#${v.toString()}#`;
        if (v instanceof CVErr) return v.toString();
        if (Array.isArray(v)) return `[${v.map((x) => show(x)).join(", ")}]`;
        if (v instanceof rt.VbArray) return `Array(${v.lo.map((lo, d) => `${lo} To ${v.hi[d]}`).join(", ")}) [${v.data.map((x) => show(x)).join(", ")}]`;
        if (v instanceof Map) return `Map {${[...v].map(([k, x]) => `${show(k)} => ${show(x)}`).join(", ")}}`;
        if (v instanceof Struct) return `{ ${Object.keys(v).map((k) => `${k}: ${show(v[k])}`).join(", ")} }`;
        try {
            const name = rt.typeName(v);
            if (typeof v.Address === "function") return `${name} ${v.Address(false, false)}`;
            return name;
        } catch {
            return "Object";
        }
    }

    /** The first place two values differ, as text (arrays and structs). */
    function difference(a, b, at) {
        if (Array.isArray(a) && Array.isArray(b)) {
            if (a.length !== b.length) return `${at || "配列"} の長さ: 期待値 ${b.length}、実際の値 ${a.length}`;
            for (let i = 0; i < a.length; i++) {
                const d = difference(a[i], b[i], `${at || ""}[${i}]`);
                if (d) return d;
            }
            return null;
        }
        if (a instanceof Struct && b instanceof Struct) {
            for (const k of new Set([...Object.keys(a), ...Object.keys(b)])) {
                const d = difference(a[k], b[k], `${at || ""}.${k}`);
                if (d) return d;
            }
            return null;
        }
        if (deepEqual(a, b)) return null;
        return at ? `${at}: 期待値 ${show(b)}、実際の値 ${show(a)}` : null;
    }

    // ------------------------------------------------------------------------ expect

    function same(a, b) {
        try {
            return rt.eq(a, b);
        } catch {
            return false;
        }
    }
    function deepEqual(a, b) {
        // Arrays made by `redim`: the same bounds and elements.
        if (a instanceof rt.VbArray || b instanceof rt.VbArray) {
            return a instanceof rt.VbArray && b instanceof rt.VbArray && deepEqual(a.lo, b.lo) && deepEqual(a.hi, b.hi) && deepEqual(a.data, b.data);
        }
        if (Array.isArray(a) || Array.isArray(b)) {
            return Array.isArray(a) && Array.isArray(b) && a.length === b.length && a.every((x, i) => deepEqual(x, b[i]));
        }
        if (a instanceof Map || b instanceof Map) {
            if (!(a instanceof Map && b instanceof Map) || a.size !== b.size) return false;
            for (const [k, v] of a) if (!b.has(k) || !deepEqual(v, b.get(k))) return false;
            return true;
        }
        if (a instanceof Struct || b instanceof Struct) {
            if (!(a instanceof Struct && b instanceof Struct)) return false;
            const keys = new Set([...Object.keys(a), ...Object.keys(b)]);
            for (const k of keys) if (!deepEqual(a[k], b[k])) return false;
            return true;
        }
        if (a instanceof CVErr || b instanceof CVErr) return a instanceof CVErr && b instanceof CVErr && a.code === b.code;
        return same(a, b);
    }
    function truthy(v) {
        try {
            return v != null && v !== rt.Nothing && (typeof v === "object" && !(v instanceof RDate) ? true : rt.cbool(v));
        } catch {
            // Text that is not a number: VBA would raise a type mismatch; a test reads it as there.
            return typeof v === "string" && v.length > 0;
        }
    }
    function compare(a, b) {
        try {
            return rt.cmp(a, b);
        } catch {
            return NaN;
        }
    }

    class Failure extends Error {
        constructor(info) {
            super(info.message);
            this.name = "ExpectFailure";
            this.info = info;
        }
    }
    /** Fails the running test: the first failure is kept, whatever the program catches afterwards. */
    function fail(matcher, negated, message, expected, actual, detail) {
        const err = new Error(message);
        const info = {
            kind: "expect",
            matcher: negated ? `not.${matcher}` : matcher,
            message: detail ? `${message}\n${detail}` : message,
            expected,
            actual,
            location: position(err.stack),
        };
        if (running !== null && running.failure === null) running.failure = info;
        throw new Failure(info);
    }

    function matchers(actual, negated) {
        const check = (matcher, pass, expected, detail) => {
            if (pass !== negated) return;
            const exp = expected === undefined ? undefined : negated ? `not ${expected}` : expected;
            const text = exp === undefined ? `expect(${show(actual)}).${negated ? "not." : ""}${matcher}() が成り立ちません` : `期待値 ${exp}、実際の値 ${show(actual)}`;
            fail(matcher, negated, text, exp === undefined ? null : exp, show(actual), negated ? null : detail);
        };
        const order = (matcher, test) => (expected) => {
            const c = compare(actual, expected);
            check(matcher, !Number.isNaN(c) && test(c), `${{ toBeGreaterThan: ">", toBeGreaterThanOrEqual: ">=", toBeLessThan: "<", toBeLessThanOrEqual: "<=" }[matcher]} ${show(expected)}`);
        };
        const length = (v) => (typeof v === "string" || Array.isArray(v) ? v.length : v instanceof Map ? v.size : undefined);
        return {
            get not() {
                return matchers(actual, !negated);
            },
            toBe: (expected) => check("toBe", same(actual, expected), show(expected)),
            toEqual: (expected) => check("toEqual", deepEqual(actual, expected), show(expected), difference(actual, expected, "")),
            toBeCloseTo(expected, digits) {
                const d = digits === undefined || digits === null ? 2 : digits;
                const ok = typeof actual === "number" && Math.abs(actual - expected) < Math.pow(10, -d) / 2;
                check("toBeCloseTo", ok, `${show(expected)}（小数第 ${d} 位まで）`);
            },
            toBeGreaterThan: order("toBeGreaterThan", (c) => c > 0),
            toBeGreaterThanOrEqual: order("toBeGreaterThanOrEqual", (c) => c >= 0),
            toBeLessThan: order("toBeLessThan", (c) => c < 0),
            toBeLessThanOrEqual: order("toBeLessThanOrEqual", (c) => c <= 0),
            toBeTruthy: () => check("toBeTruthy", truthy(actual)),
            toBeFalsy: () => check("toBeFalsy", !truthy(actual)),
            toBeEmpty: () => check("toBeEmpty", actual === null || actual === undefined),
            toBeNothing: () => check("toBeNothing", actual === null || actual === undefined || actual === rt.Nothing),
            toContain(item) {
                const ok = typeof actual === "string" ? actual.includes(rt.cstr(item)) : Array.isArray(actual) ? actual.some((x) => deepEqual(x, item)) : false;
                check("toContain", ok, `${show(item)} を含む`);
            },
            toHaveLength: (n) => check("toHaveLength", length(actual) === n, `長さ ${n}（実際の長さ ${length(actual)}）`),
            toMatch(pattern) {
                let ok = false;
                try {
                    ok = typeof actual === "string" && new RegExp(String(pattern)).test(actual);
                } catch (e) {
                    throw rt.makeError(`正規表現 ${JSON.stringify(pattern)} を解釈できません（${e.message}）`, 5017);
                }
                check("toMatch", ok, `/${pattern}/ に一致`);
            },
            toThrow(expected) {
                if (typeof actual !== "function") throw rt.makeError("`toThrow` は `expect(() => ...)` のように、引数なしのラムダに対して使います", 5);
                let thrown = null;
                try {
                    actual();
                } catch (e) {
                    if (e instanceof Failure) throw e;
                    thrown = rt.caught(e);
                }
                let ok = thrown !== null;
                let want = "エラー";
                if (typeof expected === "number") {
                    ok = ok && thrown.code === expected;
                    want = `エラー ${expected}`;
                } else if (typeof expected === "string") {
                    ok = ok && String(thrown.description).includes(expected);
                    want = `説明に ${JSON.stringify(expected)} を含むエラー`;
                }
                if (ok === negated) {
                    const got = thrown === null ? "エラーは起きませんでした" : `エラー ${thrown.code}: ${thrown.description}`;
                    fail("toThrow", negated, `期待値 ${negated ? "エラーなし" : want}、実際は ${got}`, negated ? "エラーなし" : want, got, null);
                }
            },
        };
    }
    const expect = (actual) => matchers(actual, false);

    // ------------------------------------------------------------------------ replacements (mocks)

    function scope() {
        return { msgBox: null, inputBox: null, getOpenFilename: null, getSaveAsFilename: null, run: new Map(), create: new Map(), dirs: [] };
    }
    /** The replacements in force: those of the `describe`s around the test, then the test's own. */
    const scopes = [scope()];
    const top = () => scopes[scopes.length - 1];
    function found(pick) {
        for (let i = scopes.length - 1; i >= 0; i--) {
            const v = pick(scopes[i]);
            if (v !== null && v !== undefined) return v;
        }
        return null;
    }
    function replacement(handler) {
        return { calls: [], handler: typeof handler === "function" ? handler : null };
    }
    function closeScope() {
        const s = scopes.pop();
        for (const d of s.dirs) {
            try {
                fs.rmSync(d, { recursive: true, force: true });
            } catch {
                // Still in use (Windows): left to the system's cleaning of the temporary folder.
            }
        }
    }
    const dialogMock = (kind) => (handler) => {
        const m = replacement(handler);
        top()[kind] = m;
        return m;
    };
    function mockRun(macroName, handler) {
        const m = replacement(handler);
        top().run.set(String(macroName).toLowerCase(), m);
        return m;
    }
    function mockCreateObject(progId, factory) {
        const m = replacement(factory);
        top().create.set(String(progId).toLowerCase(), m);
        return m;
    }
    function warn(text) {
        if (running !== null) running.warnings.push(text);
    }
    let options = { ci: false, eventErrors: "fail" };
    /** A dialog no test replaced: answered as the debug run does, and told (spec §14.12.6). */
    function unreplaced(what, prompt) {
        const text = `${what}（${JSON.stringify(prompt)}）は置き換えられていません。既定の応答をしました（mock${what.charAt(0).toUpperCase()}${what.slice(1)} で応答を指定できます）`;
        warn(text);
        if (options.ci && running !== null && running.failure === null) running.failure = { kind: "error", code: 445, description: text, location: position(new Error().stack) };
    }

    const h = rt.hooks;
    h.print = (line) => {
        if (running !== null) running.printed.push(line);
    };
    h.note = () => {};
    h.saved = () => {};
    h.msgBox = (prompt, buttons, title) => {
        const m = found((s) => s.msgBox);
        if (m === null) {
            unreplaced("msgBox", prompt);
            return 1;
        }
        m.calls.push({ prompt, buttons, title: title === undefined ? "" : title });
        const r = m.handler ? m.handler(prompt, buttons, title === undefined ? "" : title) : 1;
        return r === undefined || r === null ? 1 : r;
    };
    h.inputBox = (prompt, title, defaultValue) => {
        const m = found((s) => s.inputBox);
        if (m === null) {
            unreplaced("inputBox", prompt);
            return defaultValue === undefined ? false : defaultValue;
        }
        m.calls.push({ prompt, title: title === undefined ? "" : title, defaultValue: defaultValue === undefined ? null : defaultValue });
        const r = m.handler ? m.handler(prompt, title === undefined ? "" : title, defaultValue === undefined ? null : defaultValue) : defaultValue;
        return r === undefined || r === null ? false : r;
    };
    const fileDialog = (kind) => (...args) => {
        const m = found((s) => s[kind]);
        if (m === null) return undefined;
        m.calls.push({ args });
        const r = m.handler ? m.handler(...args) : false;
        return r === undefined || r === null ? false : r;
    };
    h.getOpenFilename = fileDialog("getOpenFilename");
    h.getSaveAsFilename = fileDialog("getSaveAsFilename");
    h.run = (name, args) => {
        const key = String(name).toLowerCase();
        const m = found((s) => s.run.get(key) || s.run.get(key.slice(key.lastIndexOf("!") + 1)));
        if (m === null) return undefined;
        m.calls.push({ args });
        return { value: m.handler ? m.handler(...args) : null };
    };
    h.createObject = (progId) => {
        const m = found((s) => s.create.get(String(progId).toLowerCase()));
        if (m === null) return undefined;
        m.calls.push({ progId });
        return m.handler ? m.handler() : null;
    };
    h.eventError = (e, handler) => {
        const text = `${handler.target}.${handler.event}: 実行時エラー ${e.code}: ${e.description}`;
        if (options.eventErrors === "ignore" || running === null) {
            warn(text);
            return;
        }
        if (running.failure === null) {
            running.failure = { kind: "error", code: e.code, description: `イベント ハンドラ ${handler.target}.${handler.event} のエラー: ${e.description}`, location: e.rasFile ? { file: e.rasFile, line: e.rasLine, column: 0 } : null };
        }
    };

    // ------------------------------------------------------------------------ what tests use

    function useWorkbook(file) {
        const host = rt.host();
        if (host === null || typeof host.useWorkbook !== "function") throw rt.makeError("useWorkbook はブックの代役でだけ使えます", 445);
        return host.useWorkbook(path.resolve(projectRoot(), rt.cstr(file)));
    }
    function tempDir() {
        const dir = fs.mkdtempSync(path.join(os.tmpdir(), "ras-test-"));
        top().dirs.push(dir);
        return dir;
    }
    function printed() {
        return running === null ? [] : running.printed.slice();
    }

    // ------------------------------------------------------------------------ the runner

    function fullName(node) {
        const out = [];
        for (let n = node; n !== null && n.name !== null; n = n.parent) out.unshift(n.name);
        return out;
    }
    function tests(node, out) {
        for (const c of node.children) {
            if (c.suite) tests(c, out);
            else out.push(c);
        }
        return out;
    }
    function inherited(node, mode) {
        for (let n = node; n !== null; n = n.parent) if (n.mode === mode) return true;
        return false;
    }
    /** What an error that ended a test or a hook is reported as. */
    function failureOf(err, hookName) {
        if (err instanceof Failure) return hookName ? Object.assign({}, err.info, { kind: "hook", hook: hookName }) : err.info;
        const e = rt.caught(err);
        const location = position(e.stack) || (e.rasFile ? { file: e.rasFile, line: e.rasLine, column: 0 } : null);
        const out = { kind: hookName ? "hook" : "error", code: e.code, description: e.description, location };
        if (hookName) out.hook = hookName;
        return out;
    }

    function run(given) {
        options = Object.assign({ filter: null, ci: false, bail: 0, saveWorkbooks: "failed", workbooksDir: null, timeoutMs: 10000, eventErrors: "fail", emit: () => {} }, given || {});
        const emit = options.emit;
        started = true;
        const all = tests(rootSuite, []);
        const only = all.some((t) => inherited(t, "only"));
        const wanted = (t) => options.filter === null || options.filter === "" || fullName(t).join(" > ").includes(options.filter);
        /** What is done with a test: `run`, `skip`, `todo`, or `out` (not selected: not reported). */
        const plan = (t) => {
            if (!wanted(t)) return "out";
            if (t.mode === "todo") return "todo";
            if (inherited(t, "skip") || (only && !inherited(t, "only")) || t.body === null) return "skip";
            return "run";
        };
        emit({ type: "collected", tests: all.filter((t) => plan(t) !== "out").map((t) => ({ name: fullName(t), line: t.line })) });
        const host = () => {
            const s = rt.host();
            return s !== null && typeof s.snapshot === "function" ? s : null;
        };
        let failures = 0;
        const stopped = () => options.bail > 0 && failures >= options.bail;
        const result = (t, status, extra) => {
            if (status === "failed") failures++;
            emit(Object.assign({ type: "test", name: fullName(t), line: t.line, status, durationMs: 0, printed: [], warnings: [] }, extra || {}));
        };
        const saveBooks = (t) => {
            const s = host();
            if (s === null || options.workbooksDir === null) return null;
            try {
                const base = fullName(t).join(" > ").replace(/[\\/:*?"<>|\x00-\x1f]/g, "_").slice(0, 150);
                const written = s.saveAll(path.resolve(projectRoot(), options.workbooksDir), base);
                return written.length ? written.map((f) => path.relative(projectRoot(), f).split(path.sep).join("/")) : null;
            } catch {
                return null;
            }
        };

        function runTest(t, snapshot, before, after) {
            if (host() !== null && snapshot !== null) host().restore(snapshot);
            const state = { printed: [], warnings: [], failure: null };
            emit({ type: "start", name: fullName(t), line: t.line, timeoutMs: t.timeout || options.timeoutMs });
            const startedAt = Date.now();
            scopes.push(scope());
            running = state;
            let failure = null;
            let ran = true;
            for (const [fn] of before) {
                try {
                    fn();
                } catch (e) {
                    failure = failureOf(e, "beforeEach");
                    ran = false;
                    break;
                }
            }
            if (ran) {
                try {
                    t.body(...t.args.map((a) => rt.clone(a)));
                } catch (e) {
                    failure = failureOf(e, null);
                }
            }
            for (const [fn] of after) {
                try {
                    fn();
                } catch (e) {
                    if (failure === null) failure = failureOf(e, "afterEach");
                }
            }
            // A matcher that failed inside the program's own `try` still fails the test.
            if (state.failure !== null && (failure === null || (state.failure.kind === "expect" && failure.kind !== "expect"))) failure = state.failure;
            const durationMs = Date.now() - startedAt;
            const status = failure === null ? "passed" : "failed";
            let workbook = null;
            if (options.saveWorkbooks === "always" || (options.saveWorkbooks === "failed" && status === "failed")) workbook = saveBooks(t);
            running = null;
            closeScope();
            const extra = { durationMs, printed: state.printed, warnings: state.warnings };
            if (failure !== null) extra.failure = failure;
            if (workbook !== null) extra.workbook = workbook.length === 1 ? workbook[0] : workbook;
            result(t, status, extra);
        }

        function runSuite(s, before, after) {
            const mine = tests(s, []);
            const toRun = mine.filter((t) => plan(t) === "run");
            if (toRun.length === 0 || stopped()) {
                for (const t of mine) {
                    const p = plan(t);
                    if (p === "todo" || p === "skip") result(t, p === "todo" ? "todo" : "skipped");
                    else if (p === "run") result(t, "skipped");
                }
                return;
            }
            scopes.push(scope());
            const hookState = { printed: [], warnings: [], failure: null };
            let broken = null;
            running = hookState;
            for (const fn of s.hooks.beforeAll) {
                try {
                    fn();
                } catch (e) {
                    broken = failureOf(e, "beforeAll");
                    break;
                }
            }
            running = null;
            if (broken === null && hookState.failure !== null) broken = Object.assign({}, hookState.failure, { kind: "hook", hook: "beforeAll" });
            if (broken !== null) {
                // The tests of the `describe` fail without running (spec §14.12.4).
                for (const t of mine) {
                    const p = plan(t);
                    if (p === "run") result(t, "failed", { failure: broken, printed: hookState.printed });
                    else if (p !== "out") result(t, p === "todo" ? "todo" : "skipped");
                }
                closeScope();
                return;
            }
            const snapshot = host() !== null ? host().snapshot() : null;
            const beforeEach = before.concat(s.hooks.beforeEach.map((fn) => [fn]));
            const afterEach = s.hooks.afterEach.map((fn) => [fn]).reverse().concat(after);
            for (const c of s.children) {
                if (c.suite) {
                    if (host() !== null && snapshot !== null) host().restore(snapshot);
                    runSuite(c, beforeEach, afterEach);
                    continue;
                }
                const p = plan(c);
                if (p === "out") continue;
                if (p !== "run" || stopped()) {
                    result(c, p === "todo" ? "todo" : "skipped");
                    continue;
                }
                runTest(c, snapshot, beforeEach, afterEach);
            }
            running = hookState;
            for (const fn of s.hooks.afterAll) {
                try {
                    fn();
                } catch (e) {
                    const f = failureOf(e, "afterAll");
                    emit({ type: "hookError", name: fullName(s), failure: f });
                    failures++;
                }
            }
            running = null;
            closeScope();
        }

        runSuite(rootSuite, [], []);
        emit({ type: "done", failures });
        return failures;
    }

    return {
        describe,
        test,
        it: test,
        beforeAll: hook("beforeAll"),
        afterAll: hook("afterAll"),
        beforeEach: hook("beforeEach"),
        afterEach: hook("afterEach"),
        expect,
        useWorkbook,
        tempDir,
        printed,
        mockMsgBox: dialogMock("msgBox"),
        mockInputBox: dialogMock("inputBox"),
        mockGetOpenFilename: dialogMock("getOpenFilename"),
        mockGetSaveAsFilename: dialogMock("getSaveAsFilename"),
        mockRun,
        mockCreateObject,
        run,
    };
};
